const TG=(t,m)=>`https://api.telegram.org/bot${t}/${m}`;
async function tg(e,m,b){const r=await fetch(TG(e.TELEGRAM_BOT_TOKEN,m),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(!d.ok)throw Error(d.description||m);return d.result}
async function sb(e,p,o={}){const h={apikey:e.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${e.SUPABASE_SERVICE_ROLE_KEY}`,'content-type':'application/json',...(o.headers||{})};const r=await fetch(e.SUPABASE_URL+p,{...o,headers:h}),t=await r.text();let d;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw Error(`Supabase ${r.status}: ${t}`);return d}
const esc=x=>String(x??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const KB={cancel:{inline_keyboard:[[{text:'❌ Отменить',callback_data:'cancel'}]]}};
const typeName=t=>t==='artist'?'Исполнитель':'Битмейкер';
const tableOf=t=>t==='artist'?'tracks':'beats';
const ownerOf=t=>t==='artist'?'owner_id':'beatmaker_id';
async function session(e,uid){return (await sb(e,`/rest/v1/telegram_sessions?telegram_user_id=eq.${uid}&select=*`))[0]||{state:'idle',payload:{}}}
async function state(e,uid,state,payload={}){await sb(e,'/rest/v1/telegram_sessions',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({telegram_user_id:uid,state,payload,updated_at:new Date().toISOString()})})}
async function del(e,c,id){if(!id)return;try{await tg(e,'deleteMessage',{chat_id:c,message_id:id})}catch{}}
async function answer(e,c,text,markup){const uid=c;const s=await session(e,uid);await del(e,c,s.payload?.__last_message_id);const m=await tg(e,'sendMessage',{chat_id:c,text,parse_mode:'HTML',...(markup?{reply_markup:markup}:{})});await state(e,uid,s.state,{...(s.payload||{}),__last_message_id:m.message_id});return m}
async function prompt(e,c,uid,text,markup=KB.cancel){const s=await session(e,uid);await del(e,c,s.payload?.__last_message_id);const m=await tg(e,'sendMessage',{chat_id:c,text,parse_mode:'HTML',...(markup?{reply_markup:markup}:{})});await state(e,uid,s.state,{...(s.payload||{}),__last_message_id:m.message_id});return m}
async function account(e,u){let a=(await sb(e,`/rest/v1/telegram_accounts?telegram_user_id=eq.${u.id}&select=*`))[0];if(a)return a;const email=`telegram_${u.id}@nexora.local`;let au;try{au=await sb(e,'/auth/v1/admin/users',{method:'POST',body:JSON.stringify({email,password:crypto.randomUUID()+crypto.randomUUID(),email_confirm:true})})}catch{au=(await sb(e,`/auth/v1/admin/users?email=${encodeURIComponent(email)}`,{method:'GET'}))?.users?.[0]}if(!au?.id)throw Error('Не удалось создать аккаунт');let p=(await sb(e,`/rest/v1/profiles?id=eq.${au.id}&select=*`))[0];if(!p){let code;do{code='id'+Math.floor(100000+Math.random()*900000)}while((await sb(e,`/rest/v1/profiles?profile_code=eq.${code}&select=id`)).length);await sb(e,'/rest/v1/profiles',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id:au.id,username:`tg_${u.id}`,display_name:'Nexora user',profile_type:'user',profile_code:code})})}a={telegram_user_id:u.id,profile_id:au.id,telegram_username:u.username||null};await sb(e,'/rest/v1/telegram_accounts',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(a)});return a}
async function profile(e,c,a,id=a.profile_id){const p=(await sb(e,`/rest/v1/profiles?id=eq.${id}&select=*`))[0];if(!p)return answer(e,c,'Профиль не найден.');const own=id===a.profile_id,isA=p.profile_type==='artist',rows=[];if(own){rows.push([{text:'✏️ Редактировать профиль',callback_data:'edit'}],[{text:p.telegram_channel?'🗑 Удалить привязанный tg-канал':'📢 Добавить tg-канал',callback_data:'channel'}],[{text:p.personal_telegram?'🗑 Удалить личные сообщения':'💬 Добавить личные сообщения',callback_data:'personal'}],[{text:isA?'🎵 Загрузить свою демку':'🥁 Загрузить свой бит',callback_data:'upload'}],[{text:isA?'📂 Мои демки':'📂 Мои биты',callback_data:`lib:${isA?'t':'b'}:0`}],[{text:'🤝 Запросы на коллаб',callback_data:'req:collab'}],[isA?{text:'🎵 Предложенные биты',callback_data:'req:offers'}:{text:'📝 Запросы на запись бита',callback_data:'req:beats'}],[{text:'🎧 Случайные демки',callback_data:'rnd:t'}],[{text:'🥁 Случайные биты',callback_data:'rnd:b'}],[{text:'🔗 Рефералы',callback_data:'ref'}])}else rows.push([{text:isA?'🎵 Демки профиля':'🥁 Биты профиля',callback_data:`pubs:${id}:0`}]);return answer(e,c,`👤 <b>Профиль Nexora</b>\n\nID: <code>${esc(p.profile_code)}</code>\nИмя профиля: <b>${esc(p.username)}</b>\nТип профиля: <b>${esc(typeName(p.profile_type))}</b>${p.telegram_channel?`\n📢 ${esc(p.telegram_channel)}`:''}${p.personal_telegram?`\n💬 ${esc(p.personal_telegram)}`:''}`,{inline_keyboard:rows})}
async function openProfile(e,c,a,id=a.profile_id){const m=await profile(e,c,a,id);await state(e,a.telegram_user_id,'idle',{__last_message_id:m?.message_id});return m}
async function registration(e,c,a){const old=await session(e,a.telegram_user_id);await state(e,a.telegram_user_id,'reg_type',old.state==='collab_registration'?old.payload:{});return prompt(e,c,a.telegram_user_id,'👋 <b>Регистрация Nexora</b>\n\nВыбери тип профиля:',{inline_keyboard:[[{text:'🥁 Битмейкер',callback_data:'reg:b'},{text:'🎤 Исполнитель',callback_data:'reg:a'}]]})}
async function editProfile(e,c,a){await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}`,{method:'PATCH',body:JSON.stringify({display_name:'Nexora user',profile_type:'user'})});return registration(e,c,a)}
async function beginUpload(e,c,a){const p=(await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}&select=*`))[0];if(!p||p.profile_type==='user')return registration(e,c,a);await state(e,a.telegram_user_id,'upload_file',{type:p.profile_type});return prompt(e,c,a.telegram_user_id,`📤 Пришли файл <b>MP3</b> для ${p.profile_type==='artist'?'демки':'бита'}.`)}
async function storeMp3(e,a,fileId){const f=await tg(e,'getFile',{file_id:fileId}),path=String(f.file_path||'');if(!/\.mp3$/i.test(path))throw Error('Нужен файл в формате MP3.');const r=await fetch(`https://api.telegram.org/file/bot${e.TELEGRAM_BOT_TOKEN}/${path}`);if(!r.ok)throw Error('Не удалось скачать MP3.');const objectPath=`telegram/${a.profile_id}/${crypto.randomUUID()}.mp3`;await sb(e,`/storage/v1/object/nexora-audio/${objectPath}`,{method:'POST',headers:{'content-type':'audio/mpeg','x-upsert':'false'},body:await r.arrayBuffer()});return objectPath}
const genres=s=>String(s).split(',').map(x=>x.trim().replace(/^#+/,'').toLowerCase()).filter(Boolean);
const bpmKey=s=>{const m=String(s).trim().match(/^(\d{2,3})\s*BPM\s+(.+)$/i);if(!m||+m[1]<20||+m[1]>400)return null;return{bpm:+m[1],musical_key:m[2].trim()}};
async function preview(e,c,a){const s=await session(e,a.telegram_user_id),p=s.payload,url=`${e.SUPABASE_URL}/storage/v1/object/public/nexora-audio/${p.audio}`,caption=`<b>${esc(p.title)}</b>\n${p.genres.map(x=>`#${esc(x)}`).join(', ')}\n${p.bpm} BPM ${esc(p.musical_key)}${p.coauthors?.length?`\nСоавторы: ${p.coauthors.map(esc).join(', ')}`:''}`;const m=await tg(e,'sendAudio',{chat_id:c,audio:url,title:p.title,performer:'Nexora',caption,parse_mode:'HTML',reply_markup:{inline_keyboard:[[{text:'✅ Опубликовать',callback_data:'publish'}],[{text:'✏️ Редактировать',callback_data:'editmeta'}],[{text:'❌ Отменить',callback_data:'cancel'}]]}});await state(e,a.telegram_user_id,'preview',{...p,preview:m.message_id,__last_message_id:m.message_id})}
async function notify(e,pid,text,markup){const t=(await sb(e,`/rest/v1/telegram_accounts?profile_id=eq.${pid}&select=telegram_user_id`))[0];if(t)await tg(e,'sendMessage',{chat_id:t.telegram_user_id,text,parse_mode:'HTML',...(markup?{reply_markup:markup}:{})})}
async function findProfile(e,n){return (await sb(e,`/rest/v1/profiles?username=eq.${encodeURIComponent(n.replace(/^@/,''))}&select=id,username`))[0]}
async function makeDraft(e,a,p){const body=p.type==='artist'?{owner_id:a.profile_id,title:p.title,audio_path:p.audio,genre:p.genres.join(', '),bpm:p.bpm,musical_key:p.musical_key,published:false}:{beatmaker_id:a.profile_id,title:p.title,audio_path:p.audio,genre:p.genres.join(', '),bpm:p.bpm,musical_key:p.musical_key,price_cents:0,published:false};return (await sb(e,`/rest/v1/${tableOf(p.type)}`,{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(body)}))[0]}
async function createInvite(e,a,names,p,c){p.coauthors=[];for(const raw of names){const n=raw.trim().replace(/^@/,'');if(!n)continue;const q=await findProfile(e,n);if(q){p.coauthors.push(q.username);const token=crypto.randomUUID().replaceAll('-','');try{await sb(e,'/rest/v1/collab_invites',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({inviter_id:a.profile_id,invitee_username:q.username,invite_token:token,track_id:p.type==='artist'?p.draft_id:null,beat_id:p.type==='beatmaker'?p.draft_id:null,status:'pending'})})}catch{}await notify(e,q.id,`🤝 <b>Приглашение в соавторы</b>\n\n${esc(a.telegram_username?'@'+a.telegram_username:'Пользователь')} приглашает тебя в соавторы: <b>${esc(p.title)}</b>.`,{inline_keyboard:[[{text:'✅ Принять',callback_data:`ci:a:${token}`},{text:'❌ Отклонить',callback_data:`ci:d:${token}`}]]})}else{const me=await tg(e,'getMe',{}),url=`https://t.me/${me.username}?start=collab_${encodeURIComponent(p.draft_id)}_${encodeURIComponent(a.profile_id)}_${encodeURIComponent(n)}`;p.coauthors.push(n);await answer(e,c,`👤 <b>${esc(n)}</b> не найден в Nexora.\n\nПриглашение: ${esc(url)}`,{inline_keyboard:[[{text:'📨 Поделиться приглашением',url:`https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent('Присоединяйся к Nexora')}`}]]})}}return p}
async function publish(e,c,a){const s=await session(e,a.telegram_user_id),p=s.payload;await sb(e,`/rest/v1/${tableOf(p.type)}?id=eq.${p.draft_id}&${ownerOf(p.type)}=eq.${a.profile_id}`,{method:'PATCH',body:JSON.stringify({published:true})});for(const n of p.coauthors||[]){const q=await findProfile(e,n);if(!q)continue;const path=p.type==='artist'?'/rest/v1/track_collaborators':'/rest/v1/beat_collaborators',body=p.type==='artist'?{track_id:p.draft_id,profile_id:q.id,status:'pending'}:{beat_id:p.draft_id,profile_id:q.id,status:'pending'};try{await sb(e,path,{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify(body)})}catch{}}await del(e,c,s.payload?.__last_message_id);await state(e,a.telegram_user_id,'idle',{});return profile(e,c,a)}
async function library(e,c,a,t,page=0,pid=a.profile_id){const table=t==='t'?'tracks':'beats',owner=t==='t'?'owner_id':'beatmaker_id',r=await sb(e,`/rest/v1/${table}?${owner}=eq.${pid}&published=eq.true&select=id,title,genre,bpm,musical_key&order=created_at.desc&limit=10&offset=${page*10}`);const kb=r.map(x=>[{text:x.title.slice(0,45),callback_data:pid===a.profile_id?`item:${t}:${x.id}`:`pubitem:${t}:${x.id}`}]);const nav=[];if(page)nav.push({text:'⬅️ Назад',callback_data:pid===a.profile_id?`lib:${t}:${page-1}`:`pubs:${pid}:${page-1}`});if(r.length===10)nav.push({text:'Вперёд ➡️',callback_data:pid===a.profile_id?`lib:${t}:${page+1}`:`pubs:${pid}:${page+1}`});if(nav.length)kb.push(nav);kb.push([{text:'⬅️ Профиль',callback_data:pid===a.profile_id?'profile':`pub:${pid}`}]);return answer(e,c,`📂 <b>${t==='t'?'Демки':'Биты'}</b>\n\n${r.map((x,i)=>`${i+1}. <b>${esc(x.title)}</b> — ${esc(x.genre||'')} · ${x.bpm||'?'} BPM · ${esc(x.musical_key||'')}`).join('\n')||'Пусто.'}`,{inline_keyboard:kb})}
async function sendItem(e,c,a,t,id,own=true){const table=t==='t'?'tracks':'beats',owner=t==='t'?'owner_id':'beatmaker_id',x=(await sb(e,`/rest/v1/${table}?id=eq.${id}&select=*`))[0];if(!x)return answer(e,c,'Не найдено.');if(own&&x[owner]!==a.profile_id)return answer(e,c,'Нет доступа.');return tg(e,'sendAudio',{chat_id:c,audio:`${e.SUPABASE_URL}/storage/v1/object/public/nexora-audio/${x.audio_path}`,title:x.title,performer:'Nexora',caption:`<b>${esc(x.title)}</b>\n${esc(x.genre||'')}\n${x.bpm||'?'} BPM · ${esc(x.musical_key||'')}`,parse_mode:'HTML',reply_markup:{inline_keyboard:own?[[{text:'🗑 Удалить',callback_data:`delete:${t}:${id}`}],[{text:'⬅️ Назад',callback_data:`lib:${t}:0`}]]:[[ {text:'👤 Профиль',callback_data:`pub:${x[owner]}`}]]}})}
function genreMatch(genre,wanted){const have=genres(genre);return wanted.some(w=>have.includes(w)||have.some(h=>h.includes(w)||w.includes(h)))}
async function random(e,c,a,t,wanted=[]){const table=t==='t'?'tracks':'beats',owner=t==='t'?'owner_id':'beatmaker_id',all=await sb(e,`/rest/v1/${table}?published=eq.true&select=*`),r=all.filter(x=>x[owner]!==a.profile_id&&(!wanted.length||genreMatch(x.genre,wanted)));if(!r.length)return answer(e,c,'Ничего не найдено по выбранным жанрам.');const x=r[Math.floor(Math.random()*r.length)];let co='';const coll=await sb(e,t==='t'?`/rest/v1/track_collaborators?track_id=eq.${x.id}&status=eq.accepted&select=profile_id`:`/rest/v1/beat_collaborators?beat_id=eq.${x.id}&status=eq.accepted&select=profile_id`);if(coll.length)co=`\nСоавторы: ${(await Promise.all(coll.map(async q=>(await sb(e,`/rest/v1/profiles?id=eq.${q.profile_id}&select=username`))[0]?.username))).filter(Boolean).map(esc).join(', ')}`;return tg(e,'sendAudio',{chat_id:c,audio:`${e.SUPABASE_URL}/storage/v1/object/public/nexora-audio/${x.audio_path}`,title:x.title,performer:'Nexora',caption:`<b>${esc(x.title)}</b>${co}\n${x.bpm||'?'} BPM · ${esc(x.musical_key||'')}\n${esc(x.genre||'')}`,parse_mode:'HTML',reply_markup:{inline_keyboard:[[ {text:'❤️ Лайк',callback_data:`like:${t}:${x.id}`},{text:'👤 Профиль',callback_data:`pub:${x[owner]}`}],[{text:'💬 Комментарий',callback_data:`comment:${t}:${x.id}:${x[owner]}`},{text:'➡️ Следующий',callback_data:`next:${t}`}]]}})}
async function requestList(e,c,a,k){const table=k==='offers'?'beat_offers':k==='beats'?'beat_requests':'collab_requests',r=await sb(e,`/rest/v1/${table}?recipient_id=eq.${a.profile_id}&status=neq.accepted&status=neq.declined&select=*&order=created_at.desc`);if(!r.length)return answer(e,c,'Запросов нет.');let text=k==='offers'?'🎵 <b>Предложенные биты</b>':k==='beats'?'📝 <b>Запросы на запись бита</b>':'🤝 <b>Запросы на коллаб</b>';const kb=[];for(const x of r.slice(0,20)){const pid=k==='offers'?x.sender_id:x.requester_id,p=(await sb(e,`/rest/v1/profiles?id=eq.${pid}&select=username`))[0];let z=null;if(x.beat_id)z=(await sb(e,`/rest/v1/beats?id=eq.${x.beat_id}&select=title,bpm,musical_key`))[0];if(x.track_id)z=(await sb(e,`/rest/v1/tracks?id=eq.${x.track_id}&select=title,bpm,musical_key`))[0];text+=`\n• <b>${esc(p?.username||'user')}</b> — ${esc(z?.title||'Запрос')} · ${z?.bpm||'?'} BPM · ${esc(z?.musical_key||'')}`;kb.push([{text:'👁 Открыть',callback_data:`openreq:${k}:${x.id}`},{text:'❌ Отклонить',callback_data:`decline:${k}:${x.id}`}])}return answer(e,c,text,{inline_keyboard:kb})}
async function referrals(e,c,a){const p=(await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}&select=profile_code,promotion_bonus`))[0],me=await tg(e,'getMe',{}),url=`https://t.me/${me.username}?start=ref_${p.profile_code}`,r=await sb(e,`/rest/v1/telegram_referrals?referrer_id=eq.${a.profile_id}&select=id`);return answer(e,c,`🔗 <b>Рефералы</b>\n\n${esc(url)}\n\nПриглашено: <b>${r.length}</b>\nБонус продвижения: <b>${Number(p.promotion_bonus||0).toFixed(1)}%</b>\n+0,2% за каждого приглашённого.`,{inline_keyboard:[[{text:'📨 Поделиться',url:`https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent('Заходи в Nexora')}`}],[{text:'⬅️ Профиль',callback_data:'profile'}]]})}
async function comment(e,c,a,t,id,pid){await state(e,a.telegram_user_id,'comment',{type:t,id,recipient:pid});return prompt(e,c,a.telegram_user_id,'💬 Напиши комментарий или сообщение:')}
async function like(e,a,t,id){const table=t==='t'?'track_likes':'beat_likes',col=t==='t'?'track_id':'beat_id',exists=await sb(e,`/rest/v1/${table}?${col}=eq.${id}&user_id=eq.${a.profile_id}&select=id`);if(!exists.length)try{await sb(e,`/rest/v1/${table}`,{method:'POST',body:JSON.stringify({[col]:id,user_id:a.profile_id})})}catch{}if(t==='b'){const b=(await sb(e,`/rest/v1/beats?id=eq.${id}&select=title,beatmaker_id`))[0];if(b)await notify(e,b.beatmaker_id,`❤️ <b>${esc((await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}&select=username`))[0]?.username||'Пользователь')}</b> понравился ваш бит <b>${esc(b.title)}</b>`)}}
async function cb(e,c,a,data){const s=await session(e,a.telegram_user_id),p=s.payload;if(data==='cancel'){await del(e,c,s.payload?.__last_message_id);await state(e,a.telegram_user_id,'idle',{});return profile(e,c,a)}if(data==='profile')return openProfile(e,c,a);if(data==='edit')return editProfile(e,c,a);if(data==='upload')return beginUpload(e,c,a);if(data==='channel'){const pr=(await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}&select=telegram_channel`))[0];if(pr.telegram_channel){await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}`,{method:'PATCH',body:JSON.stringify({telegram_channel:null})});return openProfile(e,c,a)}await state(e,a.telegram_user_id,'channel',{});return prompt(e,c,a.telegram_user_id,'📢 Пришли tg-канал в формате <b>@channel</b>.')}if(data==='personal'){const pr=(await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}&select=personal_telegram`))[0];if(pr.personal_telegram){await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}`,{method:'PATCH',body:JSON.stringify({personal_telegram:null})});return openProfile(e,c,a)}await state(e,a.telegram_user_id,'personal',{});return prompt(e,c,a.telegram_user_id,'💬 Пришли свой Telegram в формате <b>@username</b>.')}if(data.startsWith('reg:')){const typ=data==='reg:b'?'beatmaker':'artist',old=await session(e,a.telegram_user_id);await sb(e,`/rest/v1/profiles?id=eq.${a.profile_id}`,{method:'PATCH',body:JSON.stringify({profile_type:typ})});await state(e,a.telegram_user_id,'reg_nick',{type:typ,...(old.payload?.invite?{invite:old.payload.invite}:{})});return prompt(e,c,a.telegram_user_id,'Теперь введи <b>ник</b> профиля:')}if(data==='editmeta'){if(p.draft_id)try{await sb(e,`/rest/v1/${tableOf(p.type)}?id=eq.${p.draft_id}&${ownerOf(p.type)}=eq.${a.profile_id}`,{method:'DELETE'})}catch{}await state(e,a.telegram_user_id,'upload_title',{type:p.type,audio:p.audio});return prompt(e,c,a.telegram_user_id,'1/3 — Введи <b>название</b>:')}if(data==='publish')return publish(e,c,a);if(data.startsWith('lib:')){const[_,t,page]=data.split